// Why Code: transpose the key|value Settings tab into one object.
const rows = $input.all().map((i) => i.json);
const cfg = {};
for (const r of rows) {
  const k = String(r.key ?? '').trim();
  if (k) cfg[k] = r.value ?? '';
}
return [{ json: cfg }];

// Why Code: minute-window filter against 'now' + Luxon; native IF cannot do date deltas.
const tz = $('Pivot Settings').first().json.timezone || 'Africa/Lagos';
const now = DateTime.now().setZone(tz);
const rows = $('Read Rota').all().map((i) => i.json);
const atRisk = [];
for (const r of rows) {
  if (String(r.status).toUpperCase() !== 'PENDING') continue;
  if (String(r.escalation3hSent || '').trim()) continue;
  const start = DateTime.fromFormat(String(r.date) + ' ' + String(r.startTime), 'yyyy-MM-dd HH:mm', { zone: tz });
  if (!start.isValid) continue;
  const mins = start.diff(now, 'minutes').minutes;
  if (mins <= 165 || mins > 195) continue;  // ~3h mark; cron runs every 15 min
  atRisk.push({ ...r, minutesUntilStart: Math.round(mins) });
}
return atRisk.map((r) => ({ json: r }));

// Why Code: aggregate N at-risk rows into ONE supervisor alert; Summarize cannot build formatted prose.
const cfg = $('Pivot Settings').first().json;
const facility = cfg.facilityName || 'the facility';
const tz = cfg.timezone || 'Africa/Lagos';
const items = $input.all().map((i) => i.json);
if (!items.length) return [];
const lines = items.map((r) =>
  '- ' + r.staffName + '  |  ' + r.date + ' ' + r.startTime + '-' + r.endTime +
  '  |  ' + r.ward + '  |  Role: ' + r.role + '  |  starts in ~' + r.minutesUntilStart + ' min  |  Status: UNCONFIRMED');
const alertText = [
  'SHIFT ALERT - UNCONFIRMED SHIFT AT 3-HOUR MARK',
  '',
  'Facility: ' + facility,
  'Time:     ' + DateTime.now().setZone(tz).toFormat('yyyy-MM-dd HH:mm'),
  '',
  'The following shift assignment(s) start in about THREE HOURS and are still UNCONFIRMED:',
  '',
].concat(lines).concat([
  '',
  'ACTION REQUIRED: phone the staff member(s) now. If they cannot attend, arrange a qualified replacement immediately.',
  'Reply to staff reminders with YES when they confirm; this alert stops once the shift is confirmed in the rota sheet.',
]).join('\n');
return [{ json: {
  supervisorEmail: cfg.supervisorEmail,
  supervisorTelegramChatId: cfg.supervisorTelegramChatId,
  alertText,
  subject: '[ShiftHub] ALERT: ' + items.length + ' unconfirmed shift(s) at the 3-hour mark',
  atRiskCount: items.length,
  assignments: items.map((r) => ({ assignmentId: r.assignmentId, staffName: r.staffName,
    date: r.date, startTime: r.startTime, endTime: r.endTime, ward: r.ward, role: r.role })),
} }];

// Why Code: the Email node replaces the item payload and the native Split Out node can only read
// fields from its own input. Re-expanding the rows from the aggregation node keeps the
// 'stamp only after the alert was delivered' ordering without losing the per-row assignment ids.
const alert = $('Build Supervisor Alert').first().json;
const rows = Array.isArray(alert.assignments) ? alert.assignments : [];
return rows.map((r) => ({ json: r }));
